<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>عنوان التسليم</title>
  <link href="https://fonts.googleapis.com/css2?family=Noto+Sans+Arabic:wght@400;500;700&display=swap" rel="stylesheet">
  <style>
    :root {
      --color-bg: #f5f5f5;
      --color-card: #ffffff;
      --color-text: #333333;
      --color-border: #cccccc;
      --color-primary: #007bff;
      --color-primary-hover: #0056b3;
      --color-placeholder: #999999;
      --spacing-sm: 0.5rem;
      --spacing-md: 1rem;
      --spacing-lg: 1.5rem;
      --radius: 8px;
      --shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      padding: var(--spacing-md);
      font-family: 'Noto Sans Arabic', sans-serif;
      background-color: var(--color-bg);
      color: var(--color-text);
      line-height: 1.7;
      font-size: 16px;
      -webkit-font-smoothing: antialiased;
    }

    form {
      max-width: 400px;
      margin: 0 auto;
      background-color: var(--color-card);
      padding: var(--spacing-lg);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
    }

    .field {
      margin-bottom: var(--spacing-md);
    }

    label {
      display: block;
      margin-bottom: var(--spacing-sm);
      font-size: 14px;
      font-weight: 500;
      color: var(--color-text);
    }

    input[type="text"],
    input[type="tel"],
    select {
      width: 100%;
      padding: 0.75rem;
      border: 1px solid var(--color-border);
      border-radius: 4px;
      font-size: 16px;
      font-family: inherit;
      background-color: #fff;
      transition: border-color 0.2s ease;
    }

    input[type="text"]:focus,
    input[type="tel"]:focus,
    select:focus {
      outline: none;
      border-color: var(--color-primary);
    }

    /* حقول رقمية ذات اتجاه LTR */
    #phone,
    #makani {
      direction: ltr;
      text-align: start;
    }

    /* مؤشرات مساعدة */
    .hint {
      display: block;
      margin-top: -0.5rem;
      margin-bottom: var(--spacing-md);
      font-size: 12px;
      color: var(--color-placeholder);
    }

    /* زر الحفظ */
    button {
      width: 100%;
      padding: 0.75rem;
      background-color: var(--color-primary);
      color: #fff;
      border: none;
      border-radius: 4px;
      font-size: 16px;
      font-weight: 500;
      cursor: pointer;
      transition: background-color 0.2s ease;
    }

    button:hover {
      background-color: var(--color-primary-hover);
    }
  </style>
</head>
<body>
  <form>
    <div class="field">
      <label for="building">مبنى أو فيلا</label>
      <input type="text" id="building" name="building" placeholder="أدخل مبنى أو فيلا" dir="auto" autocomplete="address-line1">
    </div>

    <div class="field">
      <label for="street">شارع</label>
      <input type="text" id="street" name="street" placeholder="أدخل الشارع" dir="auto" autocomplete="address-line2">
    </div>

    <div class="field">
      <label for="area">منطقة</label>
      <input type="text" id="area" name="area" placeholder="أدخل المنطقة" dir="auto" autocomplete="address-level2">
    </div>

    <div class="field">
      <label for="emirate">الإمارة</label>
      <select id="emirate" name="emirate">
        <option value="Dubai" selected>دبي</option>
        <option value="Abu Dhabi">أبو ظبي</option>
        <option value="Sharjah">الشارقة</option>
        <option value="Ajman">عجمان</option>
        <option value="Ras Al Khaimah">رأس الخيمة</option>
        <option value="Fujairah">الفجيرة</option>
        <option value="Umm Al Quwain">أم القيوين</option>
      </select>
    </div>

    <div class="field">
      <label for="makani">رقم مكاني</label>
      <input type="text" id="makani" name="makani" placeholder="أدخل رقم مكاني" dir="ltr">
    </div>

    <div class="field">
      <label for="phone">رقم الهاتف</label>
      <input type="tel" id="phone" name="phone" placeholder="050 123 4567" dir="ltr" autocomplete="tel">
      <span class="hint"><bdi dir="ltr">مثال: 050 123 4567</bdi></span>
    </div>

    <button type="submit">حفظ عنوان</button>
  </form>
</body>
</html>
